#include "project.h"

#include <math.h>

#include <stdio.h>

static ForceDescription force_vector_description(Entity target, Force vector) {
    return (ForceDescription){.target = target,
        .location.reference = {.kind = ROHR_FORCE_COM_POSITION, .entity = target},
        .orientation.offset = vector.x == 0 && vector.y == 0 ? 0 :
            math_radians_to_degrees(atan2f(vector.x, vector.y)),
        .magnitude = hypotf(vector.x, vector.y)};
}


#define PLAYER_CONTACT_LIMIT 32

static const float player_move_force = 7500.0f;
static const float player_jump_force = 250000.0f;
static const float player_horizontal_speed_maximum = 260.0f;
static const float player_vertical_speed_maximum = 700.0f;

static bool ok(EngineResult result) {
    if(!rohr_error_check(result)) return true;
    fprintf(stderr, "error %d: %s\n", (int)result.result.error,
        rohr_error_message_get(result));
    return false;
}

static bool player_grounded_check(Entity player) {
    EntityContact contacts[PLAYER_CONTACT_LIMIT];
    size_t count = rohr_physics_contacts_get(
        player, contacts, PLAYER_CONTACT_LIMIT);

    for(size_t i = 0; i < count; i += 1)
        if(contacts[i].contact.detected && contacts[i].contact.normal.y < -0.5f)
            return true;
    return false;
}

static bool player_velocity_get(Entity player, Velocity *velocity) {
    EntityIndexResult index;
    if(velocity == NULL) return false;
    index = rohr_entity_index_get(player);
    if(rohr_error_check(index) || index.result.value >= velocities_pool.capacity ||
            !velocities_pool.used[index.result.value]) return false;
    *velocity = velocities[index.result.value];
    return true;
}

static bool player_speed_limit_apply(Entity player) {
    Velocity velocity;
    Velocity limited;
    if(!player_velocity_get(player, &velocity)) return false;
    limited = (Velocity){
        fmaxf(-player_horizontal_speed_maximum,
            fminf(player_horizontal_speed_maximum, velocity.x)),
        fmaxf(-player_vertical_speed_maximum,
            fminf(player_vertical_speed_maximum, velocity.y))
    };
    if(limited.x == velocity.x && limited.y == velocity.y) return true;
    return ok(rohr_physics_velocity_set(player, limited));
}

int main(void) {
    Entity root = ENTITY_INVALID, player = ENTITY_INVALID;
    InputControllerId controller = INPUT_CONTROLLER_INVALID;
    InputActionId move_action = INPUT_ACTION_INVALID, jump_action = INPUT_ACTION_INVALID;
    ViewportId viewport = VIEWPORT_INVALID;
    bool jump_queued = false;

    if(!ok(rohr_directory_working_set(rohr_directory_base_get()))) return 1;
    if(!ok(rohr_engine_start()) || !ok(rohr_graphics_start())) goto fail;
    if(!ok(project_settings_apply())) goto fail;
    InputControllerIdResult input = rohr_controller_create(project.player);
    if(rohr_error_check(input)) { fprintf(stderr, "%s\n", rohr_error_message_get(input)); goto fail; }
    controller = input.result.value;
    InputActionIdResult action = rohr_input_action_by_name_get(controller, project.player.move.name);
    if(rohr_error_check(action)) { fprintf(stderr, "%s\n", rohr_error_message_get(action)); goto fail; }
    move_action = action.result.value;
    action = rohr_input_action_by_name_get(controller, project.player.jump.name);
    if(rohr_error_check(action)) { fprintf(stderr, "%s\n", rohr_error_message_get(action)); goto fail; }
    jump_action = action.result.value;
    EntityResult created = rohr_object_create(project.player_world);
    if(rohr_error_check(created)) goto fail;
    root = created.result.value;
    EntityResult member = rohr_entity_by_name_get("player");
    if(rohr_error_check(member)) goto fail;
    player = member.result.value;
    ViewportObjectBinding binding = {&project.player_world._description,root};
    ViewportCreateDescription description = {.template=&project.game_viewport._description,.objects=&binding,.object_count=1};
    ViewportIdResult view = rohr_viewport_create(description);
    if(rohr_error_check(view)) goto fail;
    viewport = view.result.value;

    while(true) {
        SDL_Event event;
        Tick ticks_advanced;
        InputAxis1DResult move;
        Velocity velocity;
        float move_axis;

        rohr_input_frame_begin();
        while((event = rohr_engine_event_poll()).type != 0)
            if(event.type == SDL_EVENT_QUIT) goto done;
        if(rohr_input_key_pressed_check(SDL_SCANCODE_ESCAPE)) break;

        if(rohr_input_action_button_pressed_check(
                jump_action) &&
                player_grounded_check(player))
            jump_queued = true;

        if(rohr_engine_update().header.status == ROHR_REPORT_FAILED) goto fail;
        ticks_advanced = rohr_engine_tick_delta_get();
        if(ticks_advanced > 0) {
            move = rohr_input_action_axis_1d_get(
                move_action);
            move_axis = rohr_error_check(move) ? 0.0f : move.result.value;
            if(!player_velocity_get(player, &velocity))
                goto fail;
            if(move_axis != 0.0f &&
                    ((move_axis < 0.0f &&
                        velocity.x > -player_horizontal_speed_maximum) ||
                     (move_axis > 0.0f &&
                        velocity.x < player_horizontal_speed_maximum)) &&
                    !ok(rohr_physics_force_apply(force_vector_description(player, (Force){move_axis * player_move_force, 0.0f})))) goto fail;
            if(jump_queued && !ok(rohr_physics_force_apply(force_vector_description(player, (Force){0.0f, player_jump_force})))) goto fail;
            jump_queued = false;
        }

        if(rohr_physics_update(ticks_advanced).header.status == ROHR_REPORT_FAILED ||
                !player_speed_limit_apply(player)) goto fail;
        if(rohr_graphics_viewport_show(viewport).header.status == ROHR_REPORT_FAILED) goto fail;
    }

done:
    if(viewport) (void)rohr_viewport_destroy(viewport);
    if(root) (void)rohr_entity_delete(root);
    if(controller) (void)rohr_input_controller_destroy(controller);
    rohr_graphics_stop();
    rohr_engine_stop();
    return 0;
fail:
    fprintf(stderr, "Player controller example failed\n");
    if(viewport) (void)rohr_viewport_destroy(viewport);
    if(root) (void)rohr_entity_delete(root);
    if(controller) (void)rohr_input_controller_destroy(controller);
    rohr_graphics_stop();
    rohr_engine_stop();
    return 1;
}
